@push('styles')<style>.share-shell{max-width:1050px;margin:0 auto;padding:28px 20px}.share-head{display:flex;justify-content:space-between;gap:20px;margin-bottom:24px}.share-head p{color:var(--muted)}.close{font-size:32px;color:var(--muted);text-decoration:none}.invite-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:20px}.invite-card{background:#fff;border:1px solid var(--border);border-radius:20px;padding:24px;box-shadow:var(--shadow)}.invite-card.disabled{opacity:.75}.card-top{display:flex;justify-content:space-between;gap:12px}.type{color:var(--p);font-weight:700}.card-top h2{font-size:17px}.code{height:fit-content;border:0;border-radius:10px;padding:8px 12px;background:#eef2ff;color:var(--p);font-weight:800;letter-spacing:2px;cursor:pointer}.rules{display:grid;gap:7px;margin:20px 0}.usage{font-size:12px;color:var(--muted);margin-bottom:15px}.buttons,.manage{display:flex;gap:8px;flex-wrap:wrap}.buttons>*{flex:1;justify-content:center}details{margin-top:16px;border-top:1px solid var(--border);padding-top:12px}summary{cursor:pointer;color:var(--muted)}.manage{margin-top:12px}.limits{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.limits button{grid-column:1/-1}.enable{text-align:center;margin:20px}.tutorial{display:flex;align-items:center;gap:14px;background:#fff;border-radius:16px;padding:15px;margin-top:24px}.tutorial img{width:90px;height:55px;object-fit:cover;border-radius:8px}.tutorial div{flex:1;display:flex;flex-direction:column}.tutorial span{color:var(--muted);font-size:12px}@media(max-width:500px){.invite-card{padding:18px}.limits{grid-template-columns:1fr}.tutorial img{display:none}}</style>@endpush
